import { extendLesson } from "../workshops/extendLesson.js";
import { workshops } from "../workshops/api.js";
import { buildLesson as lesson, topic as t, choice as c, fill as f, bug as b, practice as p } from "../lessonBuilder.js";
const sources = [{ title: "React: synkronisering med effekter", url: "https://react.dev/learn/synchronizing-with-effects" }, { title: "React: du trenger kanskje ingen effekt", url: "https://react.dev/learn/you-might-not-need-an-effect" }, { title: "MDN: Fetch", url: "https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch" }];
export const effectLessons = [
lesson("hendelse-effekt", "En hendelse skyldes en bestemt brukerhandling. En effekt holder komponenten synkronisert med et eksternt system når relevante verdier endres.", "State, rendering som ren beregning, hendelser og import.", [
 t("synchronization", "Gjenkjenne når useEffect er relevant", "Importer useEffect fra React og kall den på toppnivå. Den kjører etter at React har oppdatert visningen. document.title er en ekstern nettleserverdi som kan synkroniseres fra en prop.", 'import { useEffect } from "react";\nfunction PageHeading({ title }) {\n  useEffect(() => { document.title = title; }, [title]);\n  return <h1>{title}</h1>;\n}', "Nettleserfanens tittel følger title. Avhengighetslisten forteller hvilke reaktive verdier effekten bruker.", c("Hvilken oppgave passer i en effekt?", "Holde nettleserfanens tittel synkron med sidens tittel.", "Lagre antall filtrerte treff i en ekstra effektstyrt statekopi.", "Opprette et nytt mål når komponenten rendres med en endret tittel.", "Fanetittelen er et eksternt system. Rene beregninger hører til rendering."), "jsx", "Skille ekstern synkronisering fra en ren beregning under rendering."),
 t("actions", "Beholde brukerhandlinger i hendelsesbehandlere", "Hvis arbeidet skjer fordi brukeren sendte inn et bestemt skjema, utfør det i submit-behandleren. Ikke lag state bare for å trigge en effekt som utfører handlingen.", 'function handleSubmit(event) {\n  event.preventDefault();\n  onCreate(title.trim());\n}', "Opprettingen skjer én gang per innsending. Rendering kan gjentas uten å opprette nye data.", b("Hva er et bedre sted for denne opprettingshandlingen?", 'useEffect(() => {\n  if (submitted) createOrder();\n}, [submitted]);', "I submit-behandleren som representerer brukerens bestilling.", "I en effekt som følger hele skjemautkastet, slik at hver endring kan sende bestillingen.", "I state-initialisereren, slik at bestillingen skjer før første visning.", "Handlingen skyldes en eksplisitt innsending. En effekt gjør årsaken mindre tydelig og kan kjøres på nytt."), "jsx", "Velge hendelsesbehandleren for en eksplisitt bestillingshandling."),
 t("derived", "Unngå effekter for avledede data", "Hvis en verdi kan beregnes fra props eller state, gjør beregningen direkte. Ekstra state og effekter gir først en rendering med gammel verdi, og så en til med oppdatert kopi.", 'const completed = tasks.filter((task) => task.done);\nconst count = completed.length;', "Antall fullførte er riktig for samme rendering som listen. Ingen synkronisering er nødvendig.", f("Fyll inn array-metoden som beregner fullførte elementer uten en effekt.", 'const doneItems = tasks.___((task) => task.done);', "filter", "Den filtrerte listen avledes fra tasks og trenger ikke egen state."), "jsx", "Identifisere array-operasjonen som avleder en liste uten ekstra state."),
], p("Skille beregning, handling og synkronisering", "Lag en målliste som beregner antall fullførte under rendering, legger til mål i en hendelse og oppdaterer document.title i en effekt.", ["Avledet antall har ingen egen setter.", "Oppretting skjer bare ved innsending.", "Fanetittelen følger relevant state gjennom en effekt med riktige avhengigheter."], ["Spør om arbeidet har et eksternt system å synkronisere med.", "Bruk ikke en effekt bare for å flytte kode ut av komponentkroppen."]), sources),
lesson("avhengigheter-cleanup", "Effekter kan starte abonnementer, tidtakere og andre eksterne forbindelser. Cleanup stopper forrige synkronisering før ny setup eller når komponenten fjernes.", "useEffect, state og hendelsesfunksjoner.", [
 t("dependencies", "Oppgi alle reaktive avhengigheter", "Props, state og funksjoner opprettet i komponenten som effekten leser er reaktive verdier. Avhengighetslisten beskriver disse; den er ikke en bryter du fritt velger for å få ønsket kjørefrekvens.", 'useEffect(() => {\n  document.title = title + " – " + section;\n}, [title, section]);', "Effekten synkroniserer når title eller section endres. Hook-linteren hjelper å oppdage utelatte verdier.", f("Fyll inn den manglende propavhengigheten.", 'useEffect(() => {\n  document.title = courseName;\n}, [___]);', "courseName", "Effekten leser courseName fra den reaktive komponentkonteksten og må følge endringer i den."), "jsx", "Identifisere en reaktiv verdi som effektens avhengighetsliste må følge."),
 t("cleanup", "Rydde opp en tidtaker", "En effekt kan returnere en funksjon. React kjører denne før neste setup med endrede avhengigheter og ved unmount. clearInterval stopper intervallet som akkurat denne setupen laget.", 'useEffect(() => {\n  const id = setInterval(() => setSeconds((s) => s + 1), 1000);\n  return () => clearInterval(id);\n}, []);', "Én aktiv tidtaker øker sekunder. Ved fjerning stoppes den. Funksjonell oppdatering unngår å lese en gammel seconds-verdi.", c("Når kjøres cleanup?", "Før ny setup etter avhengighetsendring og når komponenten fjernes.", "Bare ved unmount; avhengighetsendringer starter setup uten å avslutte den gamle.", "Etter hver ny setup, slik at den nye ressursen også fjernes straks.", "Cleanup avslutter forrige synkronisering. Utviklingsmodus kan også teste en ekstra setup/cleanup-sekvens."), "jsx", "Beskrive når React avslutter forrige effektkjøring med cleanup."),
 t("subscription", "Fjerne samme lytter som ble registrert", "addEventListener registrerer en funksjon på et eksternt objekt. removeEventListener må få samme funksjonsreferanse og hendelsestype. En ny pilfunksjon er et annet objekt selv om innholdet ligner.", 'useEffect(() => {\n  function handleOnline() { setOnline(true); }\n  window.addEventListener("online", handleOnline);\n  return () => window.removeEventListener("online", handleOnline);\n}, []);', "Lytteren fjernes på riktig måte. Hvis du også følger offline, trenger den hendelsen en tilsvarende lytter og opprydding.", b("Hvorfor fjernes ikke lytteren?", 'useEffect(() => {\n  window.addEventListener("resize", () => console.log("bredde"));\n  return () => window.removeEventListener("resize", () => console.log("bredde"));\n}, []);', "Registrering og fjerning bruker ulike funksjonsobjekter; lagre og gjenbruk samme referanse.", "Legg til [] i removeEventListener-kallet, men behold den nye pilfunksjonen.", "Behold begge pilfunksjoner; lik funksjonstekst betyr samme funksjonsobjekt.", "Funksjonsidentitet betyr noe for abonnementet. Definer én behandler inne i setup og bruk den begge steder."), "jsx", "Gjenkjenne at fjerning av en hendelseslytter krever samme funksjonsreferanse."),
], p("Lage og rydde opp et vindusabonnement", "Vis nettleservinduets bredde i en komponent. Les startverdien og abonner på resize i en effekt.", ["Visningen endres ved vindusendring.", "Lytteren fjernes når komponenten tas bort.", "Gjentatt montering lager ikke flere samtidige lyttere."], ["Logg setup og cleanup midlertidig for å forstå livsløpet.", "Bruk samme handleResize i addEventListener og removeEventListener."]), sources),
lesson("fetch-http", "fetch henter en HTTP-respons. Du må skille nettverksfeil fra HTTP-status og deretter lese responsinnholdet, ofte som JSON.", "async/await, try/catch, objekter og effekter. Eksempeladresser /api forutsetter et eget test-API eller en mock.", [
 t("response", "Kontrollere status før JSON leses", "fetch avviser ved nettverksfeil, men en 404 eller 500 gir vanligvis en vanlig Response. response.ok er true for 200–299. Kast en feil ved uventet status før du bruker dataene.", 'async function getCourses() {\n  const response = await fetch("/api/courses");\n  if (!response.ok) throw new Error(`HTTP ${response.status}`);\n  return response.json();\n}', "Kalleren får et Promise med JSON-data ved suksess og en avvisning ved feilstatus.", c("Hva skjer normalt med fetch ved HTTP 404?", "Promise-et oppfylles med en Response der ok er false.", "Promise-et avvises automatisk fordi status ikke er 2xx.", "fetch returnerer ferdig JSON med et eget error-felt for alle 404-svar.", "HTTP-feilstatus er en mottatt respons. Programmet må kontrollere status selv."), "jsx", "Skille en HTTP-feilrespons fra en avvist nettverksoperasjon."),
 t("json", "Vente på parsing og forstå datakontrakten", "response.json() er også asynkron. JSON er et tekstformat som parses til JavaScript-data; innholdet kan være array, objekt eller noe annet. Kontroller forventet form før du mapper dataene.", 'const response = await fetch("/api/tags");\nif (!response.ok) throw new Error("Kunne ikke hente emner");\nconst data = await response.json();\nif (!Array.isArray(data)) throw new Error("Uventet dataformat");', "Et svar med feil form blir en håndterbar feil i stedet for at rendering feiler senere.", f("Fyll inn metoden som leser responsinnholdet som JSON.", 'const data = await response.___();', "json", "json() leser kroppen og parser JSON. Det er ikke det samme som selve Response-objektet."), "jsx", "Identifisere metoden som parser en fetch-responskropp som JSON."),
 t("request", "Beskrive en JSON-forespørsel", "GET brukes typisk for lesing, POST for oppretting. En JSON-kropp trenger serialisering med JSON.stringify og riktig Content-Type. Ikke legg hemmelige API-nøkler i klientkode.", 'async function createTask(title) {\n  const response = await fetch("/api/tasks", {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify({ title }),\n  });\n  if (!response.ok) throw new Error("Lagring feilet");\n  return response.json();\n}', "Serveren mottar JSON-tekst. Eksemplet antar at en vellykket oppretting returnerer en JSON-kropp; ved 204 skal du ikke parse en tom kropp.", b("Hva må endres for å sende objektet som JSON?", 'fetch("/api/notes", {\n  method: "POST",\n  headers: { "Content-Type": "application/json" },\n  body: { text: "Hei" },\n});', "Bruk JSON.stringify på body-objektet.", "Behold objektet; Content-Type gjør automatisk JSON-serialisering i fetch.", "Bruk String(objektet); det gir alltid samme JSON-format som serveren forventer.", "fetch trenger en støttet kroppstype, som JSON-tekst. Et vanlig objekt serialiseres ikke automatisk til JSON."), "jsx", "Gjenkjenne manglende JSON-serialisering av en forespørselskropp."),
 t("cors", "Skille CORS fra vanlige HTTP-feil", "CORS er nettleserens kontroll av tilgang mellom ulike origins. Serveren må tillate riktig origin. mode: no-cors gjør ikke et JSON-API lesbart; det kan gi en opaque respons som JavaScript ikke får lese. Bruk et avtalt API eller en lokal fixture i øvingen.", 'const response = await fetch("/fixtures/resources.json");\nif (!response.ok) throw new Error("HTTP-feil");\nconst resources = await response.json();', "En lokal JSON-fixture på samme origin er et enkelt startpunkt. En Vite-proxy i utvikling er heller ikke en automatisk løsning for produksjonsserverens CORS.", c("Hva bør undersøkes når et eksternt API blokkeres av CORS?", "API-serverens tillatte origins og den faktiske adressekontrakten.", "Bruk mode: no-cors og les response.json() som vanlig.", "Flytt kallet til useEffect; det gir klientkoden flere CORS-rettigheter.", "CORS er en server- og nettleseravtale. Klientkode kan ikke gi seg selv fri tilgang ved å endre en React-prop."), "jsx", "Forklare at lesetilgang mellom origins må tillates av API-serveren."),
], p("Lage et lite API-lag i øvingsprosjektet", "Skriv getResources som mottar en URL. Bruk en lokal JSON-fixture eller et test-API for lesing. Ikke utfør skrivekall mot tjenester du ikke eier.", ["Funksjonen skiller OK fra HTTP-feil.", "JSON parses og forventet array-form valideres.", "Kalleren kan vise både data og en forståelig feil."], ["En statisk JSON-fil i public kan brukes for lesing uten backend.", "Prøv både en gyldig fil og en adresse som gir 404."]), sources),
lesson("last-feil-tomt", "Et nettverksgrensesnitt trenger mer enn en lykkelig slutt. Studenten skal kunne se om data lastes, om noe feilet, om resultatet er tomt, eller om data er klare.", "Fetch, try/catch, state, effekter og betinget rendering.", [
 t("states", "Skille lasting, feil, tomt og data", "Bruk en tydelig modell for tilstandene. Her er status en streng og data en liste. Feilmeldingen skal være forståelig uten å avsløre interne detaljer. Sett status før kallet og ved hvert utfall.", '// Rendering-utdrag: status, error og data kommer fra henteprosessen.\nif (status === "loading") return <p role="status">Laster ressurser…</p>;\nif (status === "error") return <p role="alert">{error}</p>;\nif (data.length === 0) return <p>Ingen ressurser ennå.</p>;\nreturn <ResourceList resources={data} />;', "De fire grenene gir ulike forklaringer. En tom liste etter suksess er ikke en feil og ikke fortsatt lasting.", c("Når skal en tomtilstand vises?", "Etter vellykket lasting der listen har null elementer.", "Så snart data er tom ved første rendering, uansett status.", "Når catch kjører, fordi et mislykket kall også betyr null resultater.", "Du må vite at lastingen lyktes før fravær av data kan tolkes som et tomt resultat."), "jsx", "Skille et vellykket tomt svar fra uavklart lasting og nettverksfeil."),
 t("flow", "Avslutte lasting i begge utfall", "En async-funksjon kan samle tilstandsbyttene. Start med loading, rydd gammel feil og sett data eller error. Funksjonen brukes av en effekt eller en eksplisitt prøv-igjen-handling avhengig av årsaken.", 'async function reload() {\n  setStatus("loading");\n  setError("");\n  try {\n    const next = await getResources();\n    setData(next);\n    setStatus("success");\n  } catch {\n    setError("Kunne ikke hente ressurser. Prøv igjen.");\n    setStatus("error");\n  }\n}', "Både suksess og feil avslutter lasting. Ved samtidige forespørsler trenger vi i tillegg beskyttelsen fra neste leksjon.", {"type":"MultipleChoiceQuestion","prompt":"API-et svarer HTTP 200 med []. Hvilken tilstand skal vises?","options":[{"id":"option-1","text":"Vellykket tomtilstand: ingen elementer."},{"id":"option-2","text":"Feil, fordi en tom array alltid betyr at transporten feilet."},{"id":"option-3","text":"Fortsatt lasting, fordi data ikke har et første element."}],"correctAnswer":"option-1","explanation":"Tom liste er gyldig data. Skill dette fra en HTTP-feil og et kall som ennå ikke har svart."}, "jsx", "Skille et vellykket tomt API-resultat fra feil og pågående lasting."),
 t("retry", "Tilby en tydelig vei videre etter feil", "En prøv-igjen-knapp kaller samme hentehandling. Unngå at gammel feil skjuler en ny forespørsel. Synlige beskjeder og riktige statusroller hjelper også tastatur- og skjermleserbrukere.", '<section>\n  <p role="alert">Kunne ikke hente listen.</p>\n  <button type="button" onClick={reload}>Prøv igjen</button>\n</section>', "Brukeren kan forsøke på nytt uten å oppdatere hele siden. reload må selv sette passende tilstander.", b("Hvorfor blir spinneren stående ved feil?", 'setLoading(true);\ntry {\n  const data = await getData();\n  setData(data);\n  setLoading(false);\n} catch { setError("Feil"); }', "loading nullstilles bare ved suksess; bruk finally eller sett false også i catch.", "Sett loading til false før await og aldri etterpå; da blir ventetiden korrekt.", "Fjern feilmeldingen slik at spinneren kan avslutte seg selv.", "Alle utfall må føre ut av lastetilstanden. finally er nyttig når samme opprydding gjelder begge utfall."), "jsx", "Identifisere en feilgren som ikke avslutter lastetilstanden."),
], p("Bygge fire testbare nettverkstilstander", "Lag en ressursvisning som kan bruke testdata for langsomt svar, feil, tom liste og vanlig liste.", ["Hver tilstand har en unik, forståelig visning.", "Prøv igjen går gjennom loading til et nytt resultat.", "Feil gir aldri en uendelig spinner."], ["Bruk en lokal kontrollert hentefunksjon før du kobler til ekte nettverk.", "Skriv ned hvordan du gjenskaper hver tilstand."]), sources),
lesson("utdaterte-svar", "Flere forespørsler kan fullføres i en annen rekkefølge enn de startet. Et gammelt svar må ikke erstatte resultatet for brukerens nyeste valg.", "Effekt-cleanup, fetch, async/await og lastetilstander.", [
 t("race", "Gjenkjenne et kappløp mellom svar", "Et kappløp oppstår når utfallet avhenger av hvilken asynkron operasjon som blir ferdig sist. Om brukeren bytter fra A til B, er det B som er gjeldende selv om A kommer sist tilbake.", '// Tidslinje, ikke kjørbar JavaScript:\n// 1. Hent A (treg)\n// 2. Hent B (rask)\n// 3. Vis B\n// 4. A kommer tilbake – må ignoreres', "Resultatet må følge gjeldende valg, ikke sist mottatte nettverkspakke.", c("Hvilket svar skal vises når gjeldende søk er B og A svarer sist?", "Resultatet for B.", "A, fordi den sist fullførte forespørselen alltid representerer siste valg.", "A frem til en tredje forespørsel starter; B skal ikke vises når A fortsatt venter.", "Brukerens gjeldende søk bestemmer hvilken forespørsel som er relevant."), "js", "Velge hvilket søkeresultat som er relevant etter et raskt valgskifte."),
 t("abort", "Avbryte fetch med AbortController", "Lag en ny AbortController for hver effektkjøring. Send signalet til fetch og avbryt i cleanup. AbortError er forventet ved avbryting og bør ikke vises som en vanlig nettverksfeil.", 'useEffect(() => {\n  const controller = new AbortController();\n  let active = true;\n  async function load() {\n    try {\n      const response = await fetch(`/api/courses/${courseId}`, { signal: controller.signal });\n      if (!response.ok) throw new Error("HTTP-feil");\n      const data = await response.json();\n      if (active) setCourse(data);\n    } catch (error) {\n      if (active && error.name !== "AbortError") setError("Henting feilet");\n    }\n  }\n  load();\n  return () => { active = false; controller.abort(); };\n}, [courseId]);', "Tidligere henting avbrytes, og active hindrer at gammel kode oppdaterer visningen. Legg også loading-status i en full implementasjon.", f("Fyll inn metoden som avbryter controllerens forespørsel i cleanup.", 'return () => controller.___();', "abort", "abort signaliserer at arbeidet ikke lenger er relevant. Det gamle signalet skal ikke gjenbrukes til en ny forespørsel."), "jsx", "Identifisere metoden som signaliserer avbryting av en aktiv fetch."),
 t("ignore", "Beskytte state også når arbeid ikke kan avbrytes", "Noen asynkrone funksjoner støtter ikke AbortSignal. Da kan en lokal active-variabel ignorere gamle resultater. cleanup setter bare variabelen for sin egen effektkjøring, ikke en global bryter.", 'useEffect(() => {\n  let active = true;\n  lookup(query).then((result) => { if (active) setResult(result); })\n    .catch(() => { if (active) setError("Søk feilet"); });\n  return () => { active = false; };\n}, [query]);', "Gamle suksesser og feil ignoreres etter at query har skiftet. Dette stopper ikke nødvendigvis selve bakgrunnsarbeidet.", b("Hvorfor beskytter ikke dette mot gamle svar?", 'useEffect(() => {\n  load(query).then(setResult);\n  return () => console.log("ryddet");\n}, [query]);', "Cleanup logger bare; resultatet må avbrytes eller kontrolleres før setResult.", "Fjern query fra avhengighetslisten; det gjør alle fremtidige svar relevante.", "Returner load(query) fra effekten; et Promise fungerer som automatisk cleanup.", "Å returnere en cleanup er ikke tilstrekkelig i seg selv. Den må faktisk gjøre gamle resultater irrelevante."), "jsx", "Gjenkjenne cleanup som ikke faktisk hindrer gamle stateoppdateringer."),
], p("Teste raskt bytte mellom to ressurser", "Lag et valg mellom to kurs med kunstig ulik svartid. Beskytt state mot svar fra tidligere valg.", ["Siste valg vinner selv når første svar kommer sist.", "Avbrutt arbeid viser ingen vanlig feilmelding.", "Suksess, feil og lasting gjelder bare aktiv forespørsel."], ["Bytt valg flere ganger mens nettverket er tregt.", "Beskytt også finally- eller loading-oppdateringer mot gammel forespørsel."]), sources),
lesson("strictmode", "StrictMode hjelper deg finne kode som ikke tåler at React kontrollerer den flere ganger i utvikling. Løs årsaken i stedet for å skjule kontrollen.", "Rene renderinger, effekter, cleanup og avbryting.", [
 t("development", "Skille utviklingskontroller fra brukerhandlinger", "StrictMode kan kalle renderingslogikk ekstra og teste effekter med setup, cleanup og setup i utvikling. Det betyr ikke at en bruker klikket to ganger. Kontrollen avdekker manglende opprydding og uren kode.", 'import { StrictMode } from "react";\nimport { createRoot } from "react-dom/client";\ncreateRoot(document.getElementById("root")).render(\n  <StrictMode><App /></StrictMode>\n);', "Utviklingskontrollene hjelper mens du arbeider. Produksjon bruker ikke disse ekstra utviklingskjøringene.", c("Hva bør du undersøke ved doble abonnementer i utvikling?", "Om effekten rydder opp abonnementet korrekt.", "Om et ref-flagg kan brukes til å hoppe over all senere setup uten cleanup.", "Om dobbelt abonnement er en nødvendig del av produksjonsoppførselen.", "Ekstra setup/cleanup avslører ofte en lekkasje som også kan oppstå ved reell remontering."), "jsx", "Forklare hva ekstra effektkjøringer i utvikling kan avdekke."),
 t("symmetric", "Lage symmetrisk setup og cleanup", "Hver setup skal eie sin egen ressurs og kunne avsluttes. Når cleanup fjerner lytteren, kan en ny setup starte uten å legge igjen kopier.", 'useEffect(() => {\n  const id = setInterval(tick, 1000);\n  return () => clearInterval(id);\n}, [tick]);', "Etter setup → cleanup → setup er bare den siste tidtakeren aktiv. tick må være en passende stabil funksjon eller defineres der den brukes med riktige avhengigheter.", f("Fyll inn oppryddingsfunksjonen for intervallet.", 'const id = setInterval(work, 1000);\nreturn () => ___(id);', "clearInterval", "Cleanup må oppheve det setupen startet. Å nullstille en stateverdi stopper ikke intervallet."), "jsx", "Identifisere funksjonen som avslutter en registrert intervallressurs."),
 t("pure-updater", "Holde oppdateringsfunksjoner rene", "React kan kontrollere en state-initialiserer eller oppdateringsfunksjon flere ganger i utvikling. Den skal bare beregne en verdi og ikke sende nettverk, skrive til lagring eller mutere en ekstern liste.", 'setCount((current) => current + 1);\n// Lagring eller varsling som skyldes klikket gjøres i hendelsen,\n// ikke som en skjult handling inne i oppdateringsfunksjonen.', "Samme input gir samme output. Dobbelt beregning lager ikke doble sideeffekter.", b("Hva er problemet med oppdateringen?", 'setTasks((current) => {\n  sendAnalytics();\n  return [...current, newTask];\n});', "Oppdateringsfunksjonen har en sideeffekt; flytt handlingen ut til riktig hendelse.", "Legg sendAnalytics i reduceren; også der er gjentatte beregninger en sikker hendelsestrigger.", "Muter current etter nettverkskallet for å markere at handlingen har kjørt.", "Oppdateringsfunksjoner må være rene. En kontrollert ekstra kjøring skal ikke sende en ekstra hendelse."), "jsx", "Gjenkjenne en sideeffekt i en stateoppdateringsfunksjon."),
], p("Kontrollere en effekt i StrictMode", "Ta tidtakeren eller abonnementet fra tidligere leksjon og monter og fjern komponenten flere ganger med StrictMode aktiv.", ["Bare én aktiv ressurs finnes etter setup/cleanup/setup.", "Rendering og oppdateringsfunksjoner muterer ingen ekstern data.", "Dokumenter hvilke logger som er utviklingskontroller og hvilke som er brukerhandlinger."], ["Ikke bruk en global 'har kjørt'-bryter for å skjule feil.", "Test at riktig oppførsel også holder ved faktisk navigasjon bort og tilbake."]), sources),
].map((item) => extendLesson(item, workshops[item.id]));
